/**
 * Single source of truth for GHOR's design tokens, generated by hand from ../DESIGN.md.
 * Consumed by apps/mobile/tailwind.config.js and apps/web/tailwind.config.ts so both
 * builds share one copy instead of two hand-kept-in-sync color palettes.
 *
 * If you change a value here, update DESIGN.md too (and vice versa) — this file and
 * DESIGN.md must never disagree. DESIGN.md is the spec; this file is its code form.
 *
 * Plain CommonJS (not TypeScript) so both a Metro-bundled RN config and a Node-executed
 * Next.js config can `require()` it without a build step.
 */

const colors = {
  primary: '#2563EB',
  'primary-pressed': '#1D4ED8',
  'primary-light': '#EFF6FF',
  'primary-disabled': '#BFDBFE',
  'on-primary': '#FFFFFF',

  ink: '#0F172A',
  body: '#1E293B',
  muted: '#64748B',
  'muted-soft': '#94A3B8',
  hairline: '#E2E8F0',
  'hairline-soft': '#F1F5F9',

  canvas: '#FFFFFF',
  surface: '#F8FAFC',
  'surface-sunken': '#F1F5F9',
  'surface-dark': '#0F172A',

  success: '#22C55E',
  'success-deep': '#15803D',
  'success-pale': '#DCFCE7',
  warning: '#F59E0B',
  'warning-deep': '#B45309',
  'warning-pale': '#FEF3C7',
  destructive: '#EF4444',
  'destructive-pressed': '#DC2626',
  'destructive-pale': '#FEE2E2',
  'focus-ring': '#93C5FD',

  'chat-sent-bg': '#2563EB',
  'chat-sent-text': '#FFFFFF',
  'chat-received-bg': '#F1F5F9',
  'chat-received-text': '#0F172A',

  // Redesign 2026-09-26 ("Blue, Navy & Cream") — depth and warmth WITHOUT a second
  // saturated brand color. Navy is a deep shade of the same blue family (hero bands,
  // sticky contact bar, dark feature blocks); cream is a warm off-white so sections can
  // alternate instead of stacking white-on-white; primary-tint is the icon-tile wash.
  navy: '#0B1B3F',
  'navy-soft': '#15295A',
  cream: '#FBF8F3',
  'cream-deep': '#F3EDE3',
  'primary-tint': '#DBEAFE',
};

// NOT wired into either tailwind.config as a scale override — see the comment in
// apps/mobile/tailwind.config.js and apps/web/tailwind.config.ts for why. Kept here as
// the documented source values; Tailwind's own `xl`/`2xl`/`3xl`/`full` already equal
// sm/md/lg/full below, so existing `rounded-xl`/`rounded-2xl`/`rounded-3xl` usage in both
// apps is already DESIGN.md-correct without renaming.
const borderRadius = {
  none: '0px',
  sm: '12px',
  md: '16px',
  lg: '24px',
  full: '9999px',
};

// DESIGN.md's spacing scale happens to land exactly on Tailwind's default 4px-based
// scale (xxs=4=spacing-1, xs=8=spacing-2, sm=12=spacing-3, md=16=spacing-4, lg=24=spacing-6,
// xl=32=spacing-8, xxl=48=spacing-12, section=64=spacing-16) — these are added as named
// aliases on top of (not replacing) Tailwind's defaults, so existing numeric utilities
// (`p-4`, `gap-6`, ...) keep working, but the token names from DESIGN.md are also usable
// (`p-md`, `gap-lg`) and preferred for anything the design system explicitly names.
const spacing = {
  xxs: '4px',
  xs: '8px',
  sm: '12px',
  md: '16px',
  lg: '24px',
  xl: '32px',
  xxl: '48px',
  section: '64px',
};

// Native system fonts only — SF Pro on iOS, Roboto on Android, matching system-ui stack
// on web. No licensed/custom face anywhere in the product. See DESIGN.md's Typography
// section and root CLAUDE.md §16.2 for why this is a deliberate MVP decision, not a
// placeholder.
const fontFamily = {
  sans: [
    '-apple-system',
    'SF Pro Text',
    'Roboto',
    'Segoe UI',
    'Helvetica Neue',
    'Arial',
    'sans-serif',
  ],
  // Web only: Geist (self-hosted via the `geist` package, exposed as --font-geist-sans in
  // apps/web/app/layout.tsx) for headings. React Native ignores the var() entry and falls
  // through to the system stack, so apps/mobile stays system-font (zero font download on
  // budget Android — DESIGN.md "Typography", amended 2026-09-26).
  display: [
    'var(--font-geist-sans)',
    '-apple-system',
    'SF Pro Display',
    'Roboto',
    'Segoe UI',
    'Helvetica Neue',
    'Arial',
    'sans-serif',
  ],
};

module.exports = { colors, borderRadius, spacing, fontFamily };
